import { useEffect, useState } from 'react';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /**
   * Inyectable para que los tests no dependan del reloj.
   *
   * `Date | undefined` a proposito (F-137): con `exactOptionalPropertyTypes`
   * activo, `now?: Date` no aceptaria que `now` llegara como `undefined`.
   */
  now?: Date | undefined;
  /**
   * Firma publica del componente: App.tsx la pasa desde el dia 1.
   *
   * Abrir un hilo lleva a MSG-02, que no existia cuando se escribio esta tarea.
   * La prop se recibe para que el repo compile y **se ignora a proposito**: no
   * cambia nada de lo que se entrega en esta pantalla.
   */
  onOpenThread?: (threadId: string) => void;
}

/** MSG-02 no esta en el alcance: la fila existe, pero no navega a ningun lado. */
const NOOP: () => void = () => undefined;

/**
 * F-128 / F-020: lo que captura un fetch fallido no siempre es un `Error`.
 *
 * PostgREST rechaza con un objeto plano `{ code, message }`: `String(e)` daria
 * `[object Object]` y `e.message` daria `undefined`. Hay que sacar `code` y/o
 * `message` cuando existan y pintarlos junto a la frase para humanos.
 */
function describeError(err: unknown): string {
  if (err !== null && typeof err === 'object') {
    const { code, message } = err as { code?: unknown; message?: unknown };
    if (typeof code === 'string' && code.length > 0) {
      return typeof message === 'string' && message.length > 0
        ? `${code} · ${message}`
        : code;
    }
    if (typeof message === 'string' && message.length > 0) return message;
  }
  if (err instanceof Error) return err.message || String(err);
  if (err !== null && typeof err === 'object') {
    try {
      return JSON.stringify(err);
    } catch {
      return String(err);
    }
  }
  return String(err);
}

export function Messages({ profile, now }: MessagesProps) {
  const [draft, setDraft] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [result, setResult] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<unknown>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    setResult(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((next) => {
        if (!cancelled) setResult(next);
      })
      .catch((failure: unknown) => {
        if (!cancelled) setError(failure);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  function applySearch() {
    setQuery(draft);
    setPage(1);
  }

  const totalPages = pageCount(result?.total ?? 0);

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSubtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      {/* El aviso con boton "Introducir frase de seguridad" no se pinta: en el
          MVP las claves viven en memoria de sesion y no hay passphrase. Solo se
          muestra el estado real de la sesion, sin acciones que no existen. */}
      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · cifrado extremo a extremo</span>
      </div>

      <div className={styles.actionBar}>
        <div className={styles.searchBox}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                applySearch();
              }
            }}
          />
        </div>

        {/* F-023-e: DIR-01 no se entrega en este MVP. El control existe porque
            es la entrada a la funcionalidad, pero va deshabilitado con el
            motivo a la vista (F-139/F-144: directorio-scope, "fuera del MVP"). */}
        <button type="button" className={styles.primaryBtn} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>

        {/* F-138: el contador de resultados lleva data-testid, no solo la clase. */}
        <span className={styles.count} data-testid="pag-info">
          {result
            ? `${result.total} ${result.total === 1 ? 'hilo' : 'hilos'} · Página ${page} de ${pageCount(result.total)}`
            : '…'}
        </span>
      </div>

      <p className={styles.scopeNote} data-testid="directorio-scope">
        El Directorio queda fuera del MVP.
      </p>

      {error !== null ? (
        <div role="alert" className={styles.errorBox}>
          <p className={styles.errorTitle}>No se pudieron cargar los hilos.</p>
          <p className={styles.errorDetail}>{describeError(error)}</p>
        </div>
      ) : null}

      {error === null && loading ? (
        <p className={styles.statusNote}>Cargando hilos…</p>
      ) : null}

      {error === null && !loading && result !== null ? (
        <>
          <ThreadList threads={result.threads} now={now} onOpen={NOOP} />
          {result.total > 0 ? (
            <div className={styles.pagination}>
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page <= 1}
                onClick={() => setPage(page - 1)}
              >
                ‹
              </button>

              {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
                <button
                  type="button"
                  key={n}
                  className={`${styles.pageBtn} ${
                    n === page ? styles.pageActive : ''
                  }`}
                  aria-current={n === page ? 'page' : undefined}
                  onClick={() => setPage(n)}
                >
                  {n}
                </button>
              ))}

              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page >= totalPages}
                onClick={() => setPage(page + 1)}
              >
                ›
              </button>
            </div>
          ) : null}
        </>
      ) : null}
    </div>
  );
}

