  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  padding: 14px 18px;
  background: transparent;
  border: none;
  border-radius: 0;
  font-family: inherit;
  text-align: left;
