  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.rowMeta {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
  text-align: right;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  border: 1px solid transparent;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ABIERTO — gris neutro */
.neutral {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

/* CON CONSULTA PENDIENTE — azul */
.info {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

/* CON OFERTA PENDIENTE — ambar */
.warn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

/* ACUERDO ALCANZADO — verde */
.success {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

/* CERRADO SIN ACUERDO — gris mas tenue con tachado. La paleta no tiene un token
   semantico para el #9BA4B0 del mock; --bw-input-placeholder lo expone con el
   valor exacto. */
.closed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

/* ── Estado vacio ─────────────────────────────────────────────────────── */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 36px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyText {
  margin: 0;
  max-width: 420px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

.emptyCta {
  height: 36px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  /* La paleta no expone un blanco puro para texto sobre azul; warm-cream es la
     superficie clara mas proxima al blanco del HTML aprobado. */
  color: var(--bw-warm-cream);
  cursor: pointer;
}

.emptyCta:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.emptyScope {
  margin: 0;
  font-size: 12px;
  color: var(--bw-input-placeholder);
}

