import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * No carga datos ni pagina: recibe las filas ya ordenadas por el servidor y las
 * pinta en el orden en que llegan. La fila es pulsable mediante un `<button>`
 * dentro del `<li>` (F-131): el `<li>` conserva su rol implicito `listitem` y el
 * boton lleva el nombre accesible del hilo.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /**
   * Inyectable para que los tests no dependan del reloj.
   *
   * Se declara `Date | undefined`, no `Date` (F-137): `exactOptionalPropertyTypes`
   * rechaza `now={now}` con `now` `undefined` si el tipo es solo `Date`.
   * `relativeTime` ya tiene su propio `now = new Date()` de respaldo en
   * `app/src/lib/threads.ts`.
   */
  now?: Date | undefined;
  /** Al abrir una fila se avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // F-141: el estado vacio va en un contenedor aparte, fuera de cualquier
    // `<ul>`. Con cero hilos no debe quedar ni un solo `listitem` en el documento.
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        {/* F-128 / F-023-e: el boton existe pero queda apagado, con su motivo a la
            vista: DIR-01 no se entrega en este MVP. */}
        <button type="button" className={styles.emptyCta} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyScope}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                <span className={styles.countryBadge}>
                  {thread.counterpartyCountry}
                </span>
              </span>
              <span className={styles.rowMeta}>
                {relativeTime(thread.lastItemAt, now)}
              </span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>
                  {previewLabel(thread.lastItem)}
                </span>
                {/* F-143: la clase del tono puede faltar en el .module.css; el
                    `?? ''` es el unico punto donde se resuelve esa ausencia. */}
                <span className={`${styles.stateBadge} ${TONE_CLASS[tone] ?? ''}`}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
